#pragma once

#include <string>
#include <string_view>

namespace ao3 {
// Caller serializes access. Secrets are generated by the device CSPRNG, never
// derived from the address, clock, MAC, username or account password.
class WebAccess {
 public:
  void reset(std::string code, std::string token) {
    pin = std::move(code);
    bearer = std::move(token);
    failures = 0;
  }
  bool pair(std::string_view code) {
    if (failures >= 5 || pin.empty()) return false;
    if (!equal(pin, code)) {
      ++failures;
      return false;
    }
    return true;
  }
  bool authorized(std::string_view token) const { return !bearer.empty() && equal(bearer, token); }
  bool locked() const { return failures >= 5; }
  const std::string& token() const { return bearer; }
  static bool sameOrigin(std::string_view host, std::string_view origin, std::string_view ip) {
    const std::string authority = std::string(ip) + ":8443";
    if (host != authority && host != "haakanpoint.local:8443") return false;
    return origin == "https://" + std::string(host);
  }

 private:
  std::string pin, bearer;
  unsigned failures = 0;
  static bool equal(std::string_view a, std::string_view b) {
    if (a.size() != b.size()) return false;
    unsigned diff = 0;
    for (size_t i = 0; i < a.size(); ++i) diff |= static_cast<unsigned char>(a[i] ^ b[i]);
    return diff == 0;
  }
};
}  // namespace ao3
